--
-- Table structure for table `assist_receita_flow`
--

DROP TABLE IF EXISTS `assist_receita_flow`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `assist_receita_flow` (
  `id` bigint(20) NOT NULL,
  `casoClinicoAcne` varchar(255) DEFAULT NULL,
  `casoClinicoFaixaEtaria` varchar(255) DEFAULT NULL,
  `casoClinicoFlacidez` varchar(255) DEFAULT NULL,
  `casoClinicoManchas` varchar(255) DEFAULT NULL,
  `casoClinicoRugas` varchar(255) DEFAULT NULL,
  `casoClinicoTipoPele` varchar(255) DEFAULT NULL,
  `dta_inclusao` datetime DEFAULT NULL,
  `dta_ult_alteracao` datetime DEFAULT NULL,
  `usuario_alteracao` varchar(255) DEFAULT NULL,
  `usuario_inclusao` varchar(255) DEFAULT NULL,
  `assistenteReceita_id` bigint(20) DEFAULT NULL,
  `atendimentoCallCenter_id` bigint(20) DEFAULT NULL,
  `medico_id` bigint(20) DEFAULT NULL,
  `paciente_id` bigint(20) DEFAULT NULL,
  `receita_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK96459E227BAAB928` (`receita_id`),
  KEY `FK96459E22A23A3DA8` (`atendimentoCallCenter_id`),
  KEY `FK96459E2232D7EE68` (`assistenteReceita_id`),
  KEY `FK96459E221E557ACC` (`paciente_id`),
  KEY `FK96459E224940104C` (`medico_id`),
  CONSTRAINT `FK96459E221E557ACC` FOREIGN KEY (`paciente_id`) REFERENCES `paciente` (`id`),
