DROP TABLE IF EXISTS `paciente`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `paciente` (
  `id` bigint(20) NOT NULL,
  `ativo` bit(1) NOT NULL,
  `bairro` varchar(255) DEFAULT NULL,
  `cep` varchar(255) DEFAULT NULL,
  `cidade` varchar(255) DEFAULT NULL,
  `complemento` varchar(255) DEFAULT NULL,
  `cpf` varchar(255) DEFAULT NULL,
  `dta_inclusao` datetime DEFAULT NULL,
  `dta_ult_alteracao` datetime DEFAULT NULL,
  `email1` varchar(255) DEFAULT NULL,
  `email2` varchar(255) DEFAULT NULL,
  `email3` varchar(255) DEFAULT NULL,
  `fone1` varchar(255) DEFAULT NULL,
  `fone2` varchar(255) DEFAULT NULL,
  `fone3` varchar(255) DEFAULT NULL,
  `logradouro` varchar(255) DEFAULT NULL,
  `nome` varchar(255) DEFAULT NULL,
  `numero` varchar(255) DEFAULT NULL,
  `observacao` longtext,
  `rg` varchar(255) DEFAULT NULL,
  `tipoLogradouro` varchar(255) DEFAULT NULL,
  `trat` varchar(255) DEFAULT NULL,
  `uf` varchar(255) DEFAULT NULL,
  `usuario_alteracao` varchar(255) DEFAULT NULL,
  `usuario_inclusao` varchar(255) DEFAULT NULL,
  `nr_registro` varchar(255) DEFAULT NULL,
  `amiga` longtext,
  `vip` varchar(255) DEFAULT NULL,
  `medico_id` bigint(20) DEFAULT NULL,
  `apelido` varchar(255) DEFAULT NULL,
  `dataNascimento` varchar(255) DEFAULT NULL,
  `fototipo` varchar(255) DEFAULT NULL,
  `sexo` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK2CA713714940104C` (`medico_id`),
  KEY `paciente_nome_idx` (`nome`),
  KEY `paciente_nome_registro_rg_cpf_idx` (`nome`,`nr_registro`,`rg`,`cpf`),
  CONSTRAINT `FK2CA713714940104C` FOREIGN KEY (`medico_id`) REFERENCES `medico` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
