DROP TABLE IF EXISTS `receita`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `receita` (
  `id` bigint(20) NOT NULL,
  `ativo` bit(1) NOT NULL,
  `dta_receita` date NOT NULL,
  `dta_inclusao` datetime DEFAULT NULL,
  `dta_ult_alteracao` datetime DEFAULT NULL,
  `receita_numero` varchar(255) NOT NULL,
  `observacao` longtext,
  `ultimoAtendimentoId` bigint(20) DEFAULT NULL,
  `usuario_alteracao` varchar(255) DEFAULT NULL,
  `usuario_inclusao` varchar(255) DEFAULT NULL,
  `justif_desc` varchar(255) DEFAULT NULL,
  `motivo_desc` varchar(255) DEFAULT NULL,
  `pct_desc` decimal(19,2) DEFAULT NULL,
  `pct_desc_adm` decimal(19,2) DEFAULT NULL,
  `vlr_subtotal` decimal(19,2) DEFAULT NULL,
  `vlr_desc` decimal(19,2) DEFAULT NULL,
  `vlr_frete` decimal(19,2) DEFAULT NULL,
  `vlr_frete_embalagem` decimal(19,2) DEFAULT NULL,
  `vlr_frete_total` decimal(19,2) DEFAULT NULL,
  `vlr_total` decimal(19,2) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

